'use strict';

function Registry() {
  this._names = [];
}

module.exports = Registry;
module.exports.defaultLimit = 10;
Registry.Registry = Registry;

Registry.prototype.register = function register(name) {
  this._names.push(name);
  return this;
};

Registry.prototype.names = function names() {
  return this._names.slice(0, Registry.defaultLimit);
};
